  if (!active || nav.indexOf(active.getAttribute('data-v')) < 0) switchView(nav[0]);
  var h = $('modeHint');
  if (h) h.innerHTML = '当前：<b>' + MODE_LABEL[m] + '</b> — ' + MODE_DESC[m];
  var sel = $('a-mode');
  if (sel) sel.value = m;
  // 地区与线路筛选只对内置 CF 节点池有意义：WARP / ${_d(a0_0x10e0cd(0x3a62,'\x24\x6f\x59\x2a')+a0_0x10e0cd(0x182e,'\x4f\x26\x43\x6f'))} 的节点由客户端直连，不参与地区/来源筛选
